from main import app
from fastapi.testclient import TestClient

def test_put_player_empty_json_object_returns_422():
    client = TestClient(app)
    response = client.put(
        '/players/squadnumber/1',
        json={}
    )
    assert response.status_code == 422

test_put_player_empty_json_object_returns_422()
